export const ListNotificationsResponseItem = zod.object({
  "id": zod.string(),
  "kind": zod.string(),
  "title": zod.string(),
  "description": zod.string(),
  "href": zod.string().nullish(),
  "isRead": zod.boolean(),
  "createdAt": zod.coerce.date()
})
export const ListNotificationsResponse = zod.array(ListNotificationsResponseItem)


/**
 * @summary Mark all notifications as read
 */
export const MarkAllNotificationsReadResponse = zod.object({
  "count": zod.number().int()
})


/**
 * @summary List conversations the current member can access
 */
export const ListConversationsResponseItem = zod.object({
  "id": zod.string(),
  "otherUserId": zod.string(),
  "otherDisplayName": zod.string(),
  "lastMessage": zod.string().nullish(),
  "lastMessageAt": zod.coerce.date().nullish(),
  "unreadCount": zod.number().int()
})
export const ListConversationsResponse = zod.array(ListConversationsResponseItem)


/**
 * @summary Read messages in a permitted conversation
 */
export const ListMessagesParams = zod.object({
  "id": zod.coerce.string()
})

export const ListMessagesResponseItem = zod.object({
  "id": zod.string(),
  "conversationId": zod.string(),
  "senderId": zod.string(),
  "senderName": zod.string(),
  "body": zod.string(),
  "createdAt": zod.coerce.date()
})
export const ListMessagesResponse = zod.array(ListMessagesResponseItem)


/**
 * @summary Send a message in a permitted conversation
 */
export const SendMessageParams = zod.object({
  "id": zod.coerce.string()
})

export const sendMessageBodyBodyMax = 2000;



export const SendMessageBody = zod.object({
  "body": zod.string().min(1).max(sendMessageBodyBodyMax)
})

export const SendMessageResponse = zod.object({
  "id": zod.string(),
  "conversationId": zod.string(),
  "senderId": zod.string(),
  "senderName": zod.string(),
  "body": zod.string(),
  "createdAt": zod.coerce.date()
})


/**
 * @summary Report a member or community item
 */
export const createReportBodyReasonMin = 3;
export const createReportBodyReasonMax = 1000;



export const CreateReportBody = zod.object({
  "targetType": zod.enum(['user', 'activity', 'project', 'message', 'community']),
  "targetId": zod.string(),
  "reason": zod.string().min(createReportBodyReasonMin).max(createReportBodyReasonMax)
})

export const CreateReportResponse = zod.object({
  "id": zod.string(),
  "status": zod.string()
})


/**
 * @summary Block a member
 */
export const BlockUserParams = zod.object({
  "id": zod.coerce.string()
})

export const BlockUserResponse = zod.void()


